<template>
  <div id="app">
    <el-tabs v-model="activeTab" type="card">
      <!-- 1. 用户注册 -->
      <el-tab-pane label="用户注册" name="register">
        <el-form :model="registerForm" label-width="80px">
          <el-form-item label="用户名">
            <el-input v-model="registerForm.username"></el-input>
          </el-form-item>
          <el-form-item label="密码">
            <el-input v-model="registerForm.password" type="password"></el-input>
          </el-form-item>
          <el-form-item label="手机号">
            <el-input v-model="registerForm.phone" placeholder="请输入11位手机号"></el-input>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click="handleRegister">注册</el-button>
          </el-form-item>
        </el-form>
      </el-tab-pane>

      <!-- 2. 发布商品 -->
      <el-tab-pane label="发布商品" name="publishGoods">
        <el-form :model="goodsForm" label-width="80px">
          <el-form-item label="商品标题">
            <el-input v-model="goodsForm.title" placeholder="必填"></el-input>
          </el-form-item>
          <el-form-item label="商品价格">
            <el-input v-model="goodsForm.price" type="number" placeholder="必填，如99.99"></el-input>
          </el-form-item>
          <el-form-item label="商品描述">
            <el-input v-model="goodsForm.description" type="textarea"></el-input>
          </el-form-item>
          <el-form-item label="卖家ID">
            <el-input v-model="goodsForm.userId" type="number" placeholder="必填，填用户表中的ID"></el-input>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click="handlePublishGoods">发布</el-button>
          </el-form-item>
        </el-form>
      </el-tab-pane>

      <!-- 3. 创建订单 -->
      <el-tab-pane label="创建订单" name="createOrder">
        <el-form :model="orderForm" label-width="80px">
          <el-form-item label="商品ID">
            <el-input v-model="orderForm.goodsId" type="number" placeholder="必填，填商品表中的ID"></el-input>
          </el-form-item>
          <el-form-item label="买家ID">
            <el-input v-model="orderForm.userId" type="number" placeholder="必填，填用户表中的ID"></el-input>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click="handleCreateOrder">创建订单</el-button>
          </el-form-item>
        </el-form>
      </el-tab-pane>
    </el-tabs>
  </div>
</template>

<script>
// 导入axios
import axios from 'axios'

export default {
  name: 'App',
  data() {
    return {
      activeTab: 'register',
      registerForm: { username: '', password: '', phone: '' },
      goodsForm: { title: '', price: 0, description: '', userId: 0 },
      orderForm: { goodsId: 0, userId: 0 }
    }
  },
  created() {
    // 全局挂载axios
    this.$axios = axios
  },
  methods: {
    // 1. 用户注册
    async handleRegister() {
      if (!this.registerForm.username || !this.registerForm.password) {
        this.$message.error('用户名和密码不能为空！');
        return;
      }
      if (this.registerForm.phone && !/^1[3-9]\d{9}$/.test(this.registerForm.phone)) {
        this.$message.error('请输入11位有效手机号！');
        return;
      }
      try {
        const res = await this.$axios.post('/api/user/register', this.registerForm);
        // 统一后端成功码200，解决矛盾提示
        if (res.data.code === 200) {
          this.$message.success(res.data.msg || '注册成功！');
          // 清空表单
          this.registerForm = { username: '', password: '', phone: '' };
        } else {
          this.$message.error('注册失败：' + res.data.msg);
        }
      } catch (err) {
        if (!err.response) {
          this.$message.error('网络连接失败，请检查后端是否启动、代理配置是否正确');
        } else {
          this.$message.error('注册出错：' + (err.response?.data?.msg || err.message));
        }
      }
    },

    // 2. 发布商品（已修复code判断，解决「发布失败：发布成功」）
    async handlePublishGoods() {
      if (!this.goodsForm.title || this.goodsForm.price <= 0 || this.goodsForm.userId <= 0) {
        this.$message.error('商品标题、价格（大于0）、卖家ID不能为空！');
        return;
      }
      try {
        const res = await this.$axios.post('/api/goods/publish', this.goodsForm);
        if (res.data.code === 200) {
          this.$message.success(res.data.msg || '发布商品成功！');
          this.goodsForm = { title: '', price: 0, description: '', userId: 0 };
        } else {
          this.$message.error('发布失败：' + res.data.msg);
        }
      } catch (err) {
        if (!err.response) {
          this.$message.error('网络连接失败，请检查后端是否启动、代理配置是否正确');
        } else {
          this.$message.error('发布出错：' + (err.response?.data?.msg || err.message));
        }
      }
    },

    // 3. 创建订单（同步统一code判断，提前规避同款bug）
    async handleCreateOrder() {
      if (this.orderForm.goodsId <= 0 || this.orderForm.userId <= 0) {
        this.$message.error('商品ID和买家ID必须大于0！');
        return;
      }
      try {
        const res = await this.$axios.post('/api/order/create', this.orderForm);
        if (res.data.code === 200) {
          this.$message.success(res.data.msg || '创建订单成功！');
          this.orderForm = { goodsId: 0, userId: 0 };
        } else {
          this.$message.error('创建失败：' + res.data.msg);
        }
      } catch (err) {
        if (!err.response) {
          this.$message.error('网络连接失败，请检查后端是否启动、代理配置是否正确');
        } else {
          this.$message.error('创建出错：' + (err.response?.data?.msg || err.message));
        }
      }
    }
  }
}
</script>

